/**
 * Nord Piano 3 (`.np3p`) reader — the Piano 3 OS 2.04 parameter containers
 * (`layout.generated.ts`, generated by scripts/gen-fw-program-maps.py) read
 * through the shared legacy program reader: record version 4 at 0x18 (version
 * 3 converted, 1 and 2 refused), the 53-byte record from file 0x1A, the 2-byte
 * trailer. See types.ts. Never throws.
 */
import { decodeLegacyProgram } from '../clavia/legacy-program';
import type { RecordConverter } from '../clavia/record-convert';
import { storedTrailerChecksum } from '../clavia/crc16';
import { NP3_LAYOUT } from './layout.generated';
import type { Np3Program } from './types';

/**
 * Version 3 → 4 (OS 2.04 load path): the converter only touches bits past the
 * 53-byte record, so a version 3 record reads as version 4 unchanged (medium:
 * the extra bits' meaning is not known). Versions 1 and 2 are refused.
 */
export const convertNp3: RecordConverter = () => [];

export function decodeNp3(bytes: Uint8Array): Np3Program {
  const p = decodeLegacyProgram(bytes, NP3_LAYOUT, { model: 'Piano 3', converted: [3], convert: convertNp3 });
  return { ...p, format: 'np3p', checksum: bytes.length >= 2 ? storedTrailerChecksum(bytes) : 0 };
}
